setInterval(() => {
  try {
    if (!serverSchedulerConfig.botActive && !serverSchedulerConfig.enabled) return;
    const current = getArgentinaTime();

    if (Array.isArray(serverSchedulerConfig.strategicSlots)) {
      for (const slot of serverSchedulerConfig.strategicSlots) {
        if (!slot.enabled) continue;
        // Check if current hour:minute matches slot.time and hasn't run today
        if (slot.time === current.timeStr && slot.lastRunDate !== current.dateStr) {
          console.log(`[🤖 Bot Auditoría Inova] Disparando horario estratégico: ${slot.time} - ${slot.name} (${current.dateStr} a las ${current.fullTimeStr} hs de Córdoba)`);
          const audit = executeServerDailyStockAnalysis(`BOT_${slot.time.replace(':', '')}`, undefined, slot);
          slot.lastRunDate = current.dateStr;
          slot.lastRunTimestamp = new Date().toISOString();
          slot.lastStatus = audit.status;
          slot.lastSummary = audit.summaryNote;
          serverSchedulerConfig.lastRunDate = current.dateStr;
          serverSchedulerConfig.lastRunTimestamp = slot.lastRunTimestamp;
          serverSchedulerConfig.lastExecutedSlot = `${slot.time} - ${slot.name}`;
          console.log(`[🤖 Bot Auditoría Inova] Completado con éxito: ${audit.summaryNote}`);
        }
      }
    }
  } catch (botErr) {
    console.error('[Bot Auditoría Inova] Error en ticker de auditoría:', botErr);
  }
}, 10 * 1000); // Check every 10 seconds

