// 2. SERVER-SIDE VALIDATION & PREFERENCE CREATION (ANTI-TAMPERING)
// -------------------------------------------------------------
app.post('/api/mercadopago/create-preference', async (req: Request, res: Response) => {
  try {
    const { 
      orderId, 
      orderNumber, 
      items, 
      customer, 
      shippingZoneId, 
      couponCode, 
      returnUrl 
    } = req.body;

    if (!items || !Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ success: false, error: 'No se incluyeron productos en el pedido.' });
    }

    // 1. Recalculate Subtotal & Verify Stock using server catalog to avoid client-side tampering
    let calculatedSubtotal = 0;
    const verifiedItems: Array<{
      id: string;
      title: string;
      unit_price: number;
      quantity: number;
      currency_id: string;
      picture_url?: string;
    }> = [];

    for (const rawItem of items) {
      const serverProduct = INITIAL_PRODUCTS.find(p => p.id === rawItem.productId || p.id === rawItem.id);
      
      // Real price lookup
      let unitPrice = serverProduct ? serverProduct.salePrice : (Number(rawItem.salePrice) || 0);
      if (serverProduct && rawItem.selectedSize && serverProduct.sizes && serverProduct.sizes.length > 0) {
        const matchedSize = serverProduct.sizes.find((s: any) => 
          s.name?.toLowerCase() === String(rawItem.selectedSize).toLowerCase() || s.id === rawItem.selectedSize
        );
        if (matchedSize && matchedSize.price) {
          unitPrice = matchedSize.price;
        }
      }
      let title = serverProduct ? serverProduct.name : (rawItem.name || 'Producto VONDRO');
      if (rawItem.selectedSize) {
        title += ` (${rawItem.selectedSize})`;
      }
      if (rawItem.selectedColor) {
        title += ` [${rawItem.selectedColor}]`;
      }
      const quantity = Math.max(1, Number(rawItem.quantity) || 1);

      // Stock check
      if (serverProduct && serverProduct.stock < quantity) {
        return res.status(400).json({
          success: false,
          error: `El producto "${title}" solo cuenta con ${serverProduct.stock} unidades en stock.`
        });
      }

      calculatedSubtotal += unitPrice * quantity;

      verifiedItems.push({
        id: serverProduct?.id || rawItem.productId || 'item',
        title,
        unit_price: unitPrice,
        quantity,
        currency_id: 'ARS',
        picture_url: serverProduct?.images[0] || rawItem.image
      });
    }

    // 2. Recalculate Shipping Cost with $80.000 free shipping rule
    const freeShippingThreshold = INITIAL_SETTINGS.freeShippingThreshold || 80000;
    const isFreeShipping = calculatedSubtotal >= freeShippingThreshold;

    const matchedZone = INITIAL_SETTINGS.zones.find(z => z.id === shippingZoneId) || INITIAL_SETTINGS.zones[0];
    const shippingCost = isFreeShipping ? 0 : (matchedZone ? matchedZone.price : 3500);

    // 3. Recalculate Coupon Discount on Server
    let discountAmount = 0;
    if (couponCode) {
      const cleanCoupon = String(couponCode).trim().toUpperCase();
      const validCoupon = INITIAL_COUPONS.find(c => c.code.toUpperCase() === cleanCoupon && c.active);
      if (validCoupon && calculatedSubtotal >= validCoupon.minPurchaseAmount) {
        if (validCoupon.discountType === 'percentage') {
          discountAmount = Math.round((calculatedSubtotal * validCoupon.value) / 100);
        } else {
          discountAmount = Math.min(calculatedSubtotal, validCoupon.value);
        }
      }
    }

    const calculatedTotal = Math.max(0, calculatedSubtotal - discountAmount + shippingCost);

    // Append shipping as an item in Mercado Pago if applicable
    if (shippingCost > 0) {
      verifiedItems.push({
        id: 'shipping_cost',
        title: `Costo de Envío - ${matchedZone?.name || 'Córdoba Capital'}`,
        unit_price: shippingCost,
        quantity: 1,
        currency_id: 'ARS'
      });
    }

    // If discount exists, adjust item prices proportionally for Mercado Pago
    const appOrigin = returnUrl || process.env.APP_URL || `http://localhost:${PORT}`;
    const cleanOrderId = orderId || `ord-${Date.now()}`;
    const cleanOrderNumber = orderNumber || `#VON-${Math.floor(1000 + Math.random() * 9000)}`;

    console.log(`[Mercado Pago] Creating preference for Order ${cleanOrderNumber}: Subtotal: $${calculatedSubtotal}, Shipping: $${shippingCost}, Discount: -$${discountAmount}, Total: $${calculatedTotal}`);

    // If real SDK client is available
    if (mpClient) {
      const preference = new Preference(mpClient);
      const preferenceResponse = await preference.create({
        body: {
          items: verifiedItems,
          payer: {
            name: customer?.firstName || 'Cliente',
            surname: customer?.lastName || 'Vondro',
            email: customer?.email || 'cliente@vondro.com',
            phone: {
              number: customer?.phone || '351000000'
            },
            address: {
              street_name: customer?.street || 'Av. Colón',
              street_number: String(customer?.number || '1234'),
              zip_code: '5000'
            }
          },
          back_urls: {
            success: `${appOrigin}/?payment_result=approved&order_id=${cleanOrderId}&order_number=${encodeURIComponent(cleanOrderNumber)}`,
            pending: `${appOrigin}/?payment_result=pending&order_id=${cleanOrderId}&order_number=${encodeURIComponent(cleanOrderNumber)}`,
            failure: `${appOrigin}/?payment_result=rejected&order_id=${cleanOrderId}&order_number=${encodeURIComponent(cleanOrderNumber)}`
          },
          auto_return: 'approved',
          external_reference: cleanOrderId,
          notification_url: `${appOrigin}/api/mercadopago/webhook`,
          statement_descriptor: 'VONDRO CORDOBA'
        }
      });

      return res.json({
        success: true,
        mode: paymentsMode,
        preferenceId: preferenceResponse.id,
        initPoint: preferenceResponse.init_point,
        sandboxInitPoint: preferenceResponse.sandbox_init_point,
        calculatedTotal,
        calculatedSubtotal,
        calculatedShipping: shippingCost,
        discountAmount,
        orderId: cleanOrderId
      });
    }

    // In Test / Simulator Mode when no live credentials are provided:
    const mockPreferenceId = `PREF-VON-${Date.now()}`;
    const testInitPoint = `${appOrigin}/?checkout_simulator=1&order_id=${cleanOrderId}&order_number=${encodeURIComponent(cleanOrderNumber)}&total=${calculatedTotal}`;

    return res.json({
      success: true,
      mode: 'test',
      isSimulated: true,
      preferenceId: mockPreferenceId,
      initPoint: testInitPoint,
      sandboxInitPoint: testInitPoint,
      calculatedTotal,
      calculatedSubtotal,
      calculatedShipping: shippingCost,
      discountAmount,
      orderId: cleanOrderId,
      note: 'Preferencia generada en Entorno TEST de Mercado Pago VONDRO.'
    });

  } catch (error: any) {
    console.error('[Mercado Pago API Error]:', error);
    return res.status(500).json({
      success: false,
      error: error.message || 'Error al conectar con la pasarela de pagos de Mercado Pago.'
    });
  }
});

